/* JavaScript Node ACM模式 控制台输入获取 */
const readline = require("readline");

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

rl.on("line", (line) => {
  const tmp = line.split(" ");
  const prefix = tmp[0];

  let find = false;
  const n = parseInt(tmp[1]);

  for (let i = 0; i < n; i++) {
    const word = tmp[i + 2];

    if (word.startsWith(prefix)) {
      find = true;
      console.log(word);
    }
  }

  if (!find) console.log(-1);
});

Java:
import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);

    String prefix = sc.next();

    boolean find = false;

    int n = sc.nextInt();
    for (int i = 0; i < n; i++) {
      String word = sc.next();

      if (word.startsWith(prefix)) {
        find = true;
        System.out.println(word);
      }
    }

    if (!find) System.out.println(-1);
  }
}

C:
#include <stdio.h>
#include <string.h>

#define MAX_LEN 1000

int main() {
    char prefix[MAX_LEN];
    scanf("%s", prefix);

    int n;
    scanf("%d", &n);

    int isFind = 0;

    for(int i=0; i<n; i++) {
        char word[MAX_LEN];
        scanf("%s", word);

        if(strncmp(prefix, word, strlen(prefix)) == 0) {
            isFind = 1;
            puts(word);
        }
    }

    if(!isFind) {
        puts("-1");
    }

    return 0;
}
